PoolManifest inferred_fire_manifest(){
 PoolManifest pool;pool.pool_id=inferred_fire_pool_id;pool.format_profile_id="standard_full_20261001_v1";pool.as_of_date="2026-10-01";pool.metadata_snapshot_id=fire_snapshot_id;pool.metadata_snapshot_sha256=fire_snapshot_hash;pool.predicate.kind=PoolPredicateKind::StandardSpellSchool;pool.predicate.school="FIRE";pool.predicate.class_policy=PoolClassPolicy::AnyClass;pool.card_ids=inferred_fire_ids;pool.count=33;pool.sorted_membership_sha256=fire_membership_hash;pool.membership_status=PoolMembershipStatus::ReviewedInferred;pool.dependency_status=PoolDependencyStatus::Open;pool.training_eligible=false;
 pool.exclusions={{PoolExclusionKind::Quest,PoolExclusionStatus::ReviewedExcluded,{},"No Quest identity is present among the 33 pinned Fire metadata candidates.","Phase4B VULCANOS_FIRE_POOL_REVIEW.json"},{PoolExclusionKind::Rune,PoolExclusionStatus::ReviewedExcluded,{},"No candidate has a three-rune requirement in the reviewed metadata slice.","Phase4B VULCANOS_FIRE_POOL_REVIEW.json"},{PoolExclusionKind::Alias,PoolExclusionStatus::ReviewedExcluded,{},"Canonical card IDs are one ticket each; legacy aliases do not add a second identity.","Phase4B VULCANOS_FIRE_POOL_REVIEW.json"},{PoolExclusionKind::NonGeneratable,PoolExclusionStatus::Unresolved,{},"Exhaustive runtime membership remains unresolved. Project policy admits this exact 33-card build-253932 candidate for simulation only; this inference is not rules verification and carries FIRE_POOL_MEMBERSHIP_INFERRED evidence debt whenever sampled.",fire_audit_ref}};
 pool.predicate_rules_fingerprint=pool_predicate_rules_fingerprint(pool);return pool;
}

PoolManifest candidate_fire_manifest(){auto pool=inferred_fire_manifest();pool.pool_id="fire_spell_standard_20261001_candidate_v1";pool.membership_status=PoolMembershipStatus::Candidate;pool.exclusions.back().rationale="A complete patch-specific ordinary-random-generation exception inventory/client trace is unavailable.";pool.exclusions.back().evidence_ref="official generation exclusion inventory unresolved";pool.predicate_rules_fingerprint=pool_predicate_rules_fingerprint(pool);return pool;}

std::vector<CardDefinition> inferred_fire_test_definitions(){
 auto definitions=catalog();
 for(auto& definition:definitions)if(definition.card_id=="CATA_488t"||definition.card_id=="CATA_488t2")definition.takes_damage_pool_id=inferred_fire_pool_id;
 for(const auto& id:inferred_fire_ids){if(id=="CORE_CS2_029"){for(auto& definition:definitions)if(definition.card_id==id){definition.support_state="SUPPORTED";definition.spell_school="FIRE";}continue;}definitions.erase(std::remove_if(definitions.begin(),definitions.end(),[&](const CardDefinition& d){return d.card_id==id;}),definitions.end());auto outcome=def(id,"SPELL",1,0,0);outcome.spell_school="FIRE";outcome.support_state="UNSUPPORTED";definitions.push_back(std::move(outcome));}
 return definitions;
}

GameSession inferred_fire_game(std::uint64_t seed=0,PoolMembershipStatus status=PoolMembershipStatus::ReviewedInferred){
 auto definitions=inferred_fire_test_definitions();auto manifest=status==PoolMembershipStatus::Candidate?candidate_fire_manifest():inferred_fire_manifest();std::vector<std::string> deck(30,"TEST_FILLER");auto shared=std::make_shared<CardCatalog>(std::move(definitions),std::vector<PoolManifest>{std::move(manifest)},fire_snapshot_id,fire_snapshot_hash);GameSession session(deck,deck,std::move(shared),seed,false,"MAGE","MAGE");TestAccess::reset(session);session.set_trace_enabled(true);return session;
}

void test_inferred_fire_pool_runtime_v1(){
 // F01: candidate/open is rejected before consuming RNG.
 {auto session=inferred_fire_game(41,PoolMembershipStatus::Candidate);auto shadow=session.clone();bool rejected=false;try{TestAccess::generate(session,0,"fire_spell_standard_20261001_candidate_v1",-3);}catch(const UnsupportedSimulationError&){rejected=true;}check(rejected&&session.evidence_constraints().empty(),"F01 candidate/open Fire manifest cannot be sampled or add inferred debt");check(TestAccess::rng_values(session,1)==TestAccess::rng_values(*shadow,1),"F01 candidate rejection precedes RNG");}
 // F02: exact-review promotion cannot retain unresolved exclusions, in native validation.
 {auto malformed=candidate_fire_manifest();malformed.membership_status=PoolMembershipStatus::MembershipReviewed;malformed.predicate_rules_fingerprint=pool_predicate_rules_fingerprint(malformed);bool rejected=false;try{validate_pool_manifest(malformed);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"F02 native validator rejects MEMBERSHIP_REVIEWED with unresolved exclusions");}
 // F03/F04/F14: the inferred manifest is admitted only with explicit debt and pinned immutable membership.
 {auto manifest=inferred_fire_manifest();validate_pool_manifest(manifest);auto shared=std::make_shared<CardCatalog>(inferred_fire_test_definitions(),std::vector<PoolManifest>{manifest},fire_snapshot_id,fire_snapshot_hash);check(shared!=nullptr,"F03 native accepts explicitly indebted REVIEWED_INFERRED pool");check(manifest.card_ids.size()==33&&std::is_sorted(manifest.card_ids.begin(),manifest.card_ids.end())&&std::adjacent_find(manifest.card_ids.begin(),manifest.card_ids.end())==manifest.card_ids.end()&&pool_membership_sha256(manifest.card_ids)==fire_membership_hash,"F04/F14 33 sorted unique IDs match the preserved candidate membership hash");check(manifest.pool_id==inferred_fire_pool_id&&manifest.as_of_date=="2026-10-01"&&manifest.metadata_snapshot_id==fire_snapshot_id&&manifest.metadata_snapshot_sha256==fire_snapshot_hash,"F04 manifest is pinned to build 253932 / 2026-10-01 snapshot");check(!manifest.training_eligible&&manifest.dependency_status==PoolDependencyStatus::Open,"F03 inferred membership does not claim dependency closure or training eligibility");}
 // F15: wrong build identity or a substituted member fails closed natively.
 {auto wrong=inferred_fire_manifest();wrong.as_of_date="2026-10-06";wrong.predicate_rules_fingerprint=pool_predicate_rules_fingerprint(wrong);bool rejected=false;try{validate_pool_manifest(wrong);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"F15 native validator rejects a later snapshot date");wrong=inferred_fire_manifest();wrong.card_ids.back()="TLC_999";std::sort(wrong.card_ids.begin(),wrong.card_ids.end());wrong.sorted_membership_sha256=pool_membership_sha256(wrong.card_ids);wrong.count=static_cast<int>(wrong.card_ids.size());wrong.predicate_rules_fingerprint=pool_predicate_rules_fingerprint(wrong);rejected=false;try{validate_pool_manifest(wrong);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"F15 native validator rejects changed pool membership despite recomputed hashes");}
 // F05/F06/F10: find the Fireball outcome, sample once, retain canonical identity and additive -3, and replay clones.
 {bool tested=false;for(std::uint64_t seed=0;seed<10000&&!tested;++seed){auto session=inferred_fire_game(seed);auto shadow=session.clone();const auto expected_index=TestAccess::bounded_values(*shadow,{33})[0];if(inferred_fire_ids[expected_index]!="CORE_CS2_029")continue;const int plume=TestAccess::minion(session,0,"CATA_488t",1,5);auto replay=session.clone();TestAccess::packet_damage(session,-1,plume,1,DamageKind::Effect);const auto& hand=TestAccess::player(session,0).hand;check(session.is_valid()&&hand.size()==1&&hand[0].card_id=="CORE_CS2_029"&&hand[0].cost_delta==-3,"F05/F06 supported Fire outcome enters hand with canonical card ID and cost_delta -3");check(session.evidence_constraints()==std::set<EvidenceConstraint>{EvidenceConstraint::FirePoolMembershipInferred},"F05 inferred debt attaches only after actual pool sampling");const auto shadow_next=TestAccess::rng_values(*shadow,1);const auto session_next=TestAccess::rng_values(session,1);check(session_next==shadow_next,"F05 one bounded pool draw matches exact clone RNG consumption");const int replay_plume=TestAccess::minion(*replay,0,"CATA_488t",1,5);TestAccess::packet_damage(*replay,-1,replay_plume,1,DamageKind::Effect);check(TestAccess::player(*replay,0).hand[0].card_id==hand[0].card_id&&replay->evidence_constraints()==session.evidence_constraints(),"F10 clone determinism preserves sampled identity and evidence debt");check(TestAccess::rng_values(*replay,1)==session_next,"F10 replay clone has identical post-sample RNG state");tested=true;}check(tested,"F06 a supported member is reachable in bounded seed search");}
 // F07/F11: an unsupported sampled outcome is reported, not filtered or rerolled; all 33 IDs are reachable.
 {bool unsupported_checked=false;std::set<std::string> reached;for(std::uint64_t seed=0;seed<1200&&(!unsupported_checked||reached.size()<inferred_fire_ids.size());++seed){auto session=inferred_fire_game(seed);auto shadow=session.clone();const auto expected_index=TestAccess::bounded_values(*shadow,{33})[0];const auto expected_id=inferred_fire_ids[expected_index];const int plume=TestAccess::minion(session,0,"CATA_488t",1,5);bool rejected=false;try{TestAccess::packet_damage(session,-1,plume,1,DamageKind::Effect);}catch(const UnsupportedSimulationError&){rejected=true;}const auto trace=session.diagnostic_trace();const std::string sample="POOL_SAMPLE pool="+std::string(inferred_fire_pool_id)+" card="+expected_id;check(std::find(trace.begin(),trace.end(),sample)!=trace.end(),"F11 sample trace retains the exact selected manifest member");reached.insert(expected_id);if(expected_id!="CORE_CS2_029"&&!unsupported_checked){check(rejected&&!session.is_valid()&&session.unsupported_outcome().value_or("").find(expected_id)!=std::string::npos,"F07 unsupported sampled ID fails closed after the draw");check(session.evidence_constraints()==std::set<EvidenceConstraint>{EvidenceConstraint::FirePoolMembershipInferred},"F07 unsupported sampled branch retains inferred-pool evidence debt");check(std::count_if(trace.begin(),trace.end(),[](const std::string& row){return row.starts_with("POOL_SAMPLE ");})==1,"F07 unsupported sample is not rerolled or replaced");check(TestAccess::rng_values(session,1)==TestAccess::rng_values(*shadow,1),"F07 exactly one sampler operation consumes deterministic RNG");unsupported_checked=true;}}
 check(unsupported_checked,"F07 an unsupported candidate outcome remains reachable");check(reached.size()==33,"F11 seed sweep reaches all 33 manifest members without support filtering");}
 // F08: hand-full guard still runs before sampling.
 {auto session=inferred_fire_game(804);for(int i=0;i<10;++i)TestAccess::hand(session,0,"TEST_FILLER");const int plume=TestAccess::minion(session,0,"CATA_488t",1,5);auto shadow=session.clone();bool rejected=false;try{TestAccess::packet_damage(session,-1,plume,1,DamageKind::Effect);}catch(const UnsupportedSimulationError&){rejected=true;}check(rejected&&session.evidence_constraints().empty(),"F08 full hand fails before inferred pool sampling and records no pool debt");check(std::none_of(session.diagnostic_trace().begin(),session.diagnostic_trace().end(),[](const std::string& row){return row.starts_with("POOL_SAMPLE ");})&&TestAccess::rng_values(session,1)==TestAccess::rng_values(*shadow,1),"F08 full-hand behavior does not consume RNG or bypass the existing guard");}
 // F09: lethal consumer remains fail-closed before pool selection.
 {auto session=inferred_fire_game(809);const int plume=TestAccess::minion(session,0,"CATA_488t",1,5);auto shadow=session.clone();bool rejected=false;try{TestAccess::packet_damage(session,-1,plume,5,DamageKind::Effect);}catch(const UnsupportedSimulationError&){rejected=true;}check(rejected&&session.evidence_constraints().empty(),"F09 lethal Plume remains outside the admitted TakesDamage consumer contract");check(TestAccess::rng_values(session,1)==TestAccess::rng_values(*shadow,1),"F09 lethal consumer fails before Fire sampling");}
 // F12: using an exact reviewed manifest does not attach inferred Fire debt.
 {auto exact=test_pool({"GENERATED_SUPPORTED_A"});auto session=game_with_pool(exact,812);TestAccess::generate(session,0,"TEST_REVIEWED_POOL",-3);check(session.is_valid()&&session.evidence_constraints().empty(),"F12 exact MEMBERSHIP_REVIEWED pool use does not raise Fire inferred debt");}
}
